{
  "source_url": "https://github.com/ethereum/EIPs/blob/master/EIPS/eip-7825.md",
  "title": "EIP-7825: Transaction Gas Limit Cap",
  "category": "EIP",
  "type": "Standards Track / Core",
  "status": "Final",
  "layer": "execution",
  "sub_graphs": [
    {
      "id": "SG-GAS-CAP-CONSTANT",
      "name": "Transaction Gas Limit Cap Constant",
      "description": "Defines the protocol-level constant MAX_TRANSACTION_GAS_LIMIT = 16,777,216 (2^24). This is the hard upper bound on the gasLimit field of any individual transaction, independent of the block gas limit.",
      "invariants": [
        {
          "id": "INV-GAS-CAP-001",
          "text": "MAX_TRANSACTION_GAS_LIMIT = 2^24 = 16,777,216. This constant is fixed at the protocol level and does not change with block gas limit adjustments."
        },
        {
          "id": "INV-GAS-CAP-002",
          "text": "The transaction gas cap is strictly independent of the block gas limit. The block gas limit may exceed 16,777,216, but no single transaction within that block may have a gasLimit exceeding 16,777,216."
        }
      ],
      "functions": [],
      "state_variables": [
        {
          "id": "SV-GAS-CAP-001",
          "name": "MAX_TRANSACTION_GAS_LIMIT",
          "type": "uint64",
          "value": "16777216",
          "description": "Protocol-level constant defining the maximum gas any single transaction may specify. Equal to 2^24."
        }
      ],
      "data_structures": [],
      "pre_conditions": [],
      "post_conditions": [],
      "state_transitions": [],
      "security_notes": [
        "The power-of-two boundary (2^24) simplifies implementation and bitwise comparisons in client code."
      ]
    },
    {
      "id": "SG-TXPOOL-VALIDATION",
      "name": "Transaction Pool Validation Gate",
      "description": "Enforces the gas limit cap at the transaction pool (mempool) ingestion layer. Transactions with gasLimit > MAX_TRANSACTION_GAS_LIMIT are rejected before entering the txpool.",
      "invariants": [
        {
          "id": "INV-TXPOOL-001",
          "text": "No transaction in the txpool shall have a gasLimit exceeding MAX_TRANSACTION_GAS_LIMIT (16,777,216)."
        }
      ],
      "functions": [
        {
          "id": "FN-TXPOOL-001",
          "signature": "validateTransaction(tx) -> (valid: bool, error: string)",
          "description": "During transaction validation at txpool ingestion, if tx.gasLimit > 16,777,216, the transaction is invalidated and not included in the txpool. Returns error code MAX_GAS_LIMIT_EXCEEDED.",
          "pseudo_logic": "if tx.gasLimit > MAX_TRANSACTION_GAS_LIMIT: return (false, 'MAX_GAS_LIMIT_EXCEEDED')"
        }
      ],
      "state_variables": [],
      "data_structures": [],
      "pre_conditions": [
        {
          "id": "PRE-TXPOOL-001",
          "text": "A transaction is submitted to the node for inclusion in the txpool."
        }
      ],
      "post_conditions": [
        {
          "id": "POST-TXPOOL-001",
          "text": "If tx.gasLimit > 16,777,216, the transaction is rejected with MAX_GAS_LIMIT_EXCEEDED and does NOT enter the txpool."
        },
        {
          "id": "POST-TXPOOL-002",
          "text": "If tx.gasLimit <= 16,777,216, the transaction proceeds through remaining validation checks (signature, nonce, balance, etc.)."
        }
      ],
      "state_transitions": [
        {
          "id": "ST-TXPOOL-001",
          "from_state": "Transaction received by node",
          "to_state": "Transaction rejected (not in txpool)",
          "trigger": "tx.gasLimit > MAX_TRANSACTION_GAS_LIMIT",
          "description": "Transactions exceeding the gas cap are immediately rejected at the txpool validation layer, preventing propagation through the network."
        },
        {
          "id": "ST-TXPOOL-002",
          "from_state": "Transaction received by node",
          "to_state": "Transaction enters txpool (pending further validation)",
          "trigger": "tx.gasLimit <= MAX_TRANSACTION_GAS_LIMIT",
          "description": "Transactions within the gas cap pass this validation gate and continue to subsequent txpool admission checks."
        }
      ],
      "security_notes": [
        "This is the first line of defense: prevents over-gas transactions from consuming txpool resources or being gossiped to peers.",
        "Mitigates DoS at the mempool level by rejecting oversized transactions before they consume validation resources."
      ]
    },
    {
      "id": "SG-BLOCK-VALIDATION",
      "name": "Block-Level Transaction Gas Limit Validation",
      "description": "Enforces the gas limit cap at the block validation layer. Any block containing a transaction with gasLimit > MAX_TRANSACTION_GAS_LIMIT is deemed invalid and rejected during consensus processing.",
      "invariants": [
        {
          "id": "INV-BLOCK-001",
          "text": "For every transaction tx in a valid block: tx.gasLimit <= MAX_TRANSACTION_GAS_LIMIT (16,777,216)."
        },
        {
          "id": "INV-BLOCK-002",
          "text": "A block is invalid if ANY transaction within it has gasLimit > 16,777,216, regardless of the block's total gas limit."
        }
      ],
      "functions": [
        {
          "id": "FN-BLOCK-001",
          "signature": "validateBlock(block) -> (valid: bool, error: string)",
          "description": "During block validation (before transaction processing/execution), iterates over all transactions in the block. If any transaction has gasLimit > 16,777,216, the entire block is rejected as invalid.",
          "pseudo_logic": "for tx in block.transactions: if tx.gasLimit > MAX_TRANSACTION_GAS_LIMIT: return (false, 'INVALID_BLOCK: transaction gas limit exceeds cap')"
        }
      ],
      "state_variables": [],
      "data_structures": [],
      "pre_conditions": [
        {
          "id": "PRE-BLOCK-001",
          "text": "A block is received by a node for validation (either from the network or produced locally)."
        }
      ],
      "post_conditions": [
        {
          "id": "POST-BLOCK-001",
          "text": "If any tx in block has gasLimit > 16,777,216, the block is rejected as invalid and not appended to the chain."
        },
        {
          "id": "POST-BLOCK-002",
          "text": "If all transactions have gasLimit <= 16,777,216, the block proceeds to further consensus validation steps."
        }
      ],
      "state_transitions": [
        {
          "id": "ST-BLOCK-001",
          "from_state": "Block received for validation",
          "to_state": "Block rejected as invalid",
          "trigger": "Any tx in block has gasLimit > MAX_TRANSACTION_GAS_LIMIT",
          "description": "Blocks containing any over-gas-cap transaction are entirely rejected during the pre-execution validation phase."
        },
        {
          "id": "ST-BLOCK-002",
          "from_state": "Block received for validation",
          "to_state": "Block passes gas cap validation (proceeds to execution)",
          "trigger": "All tx in block have gasLimit <= MAX_TRANSACTION_GAS_LIMIT",
          "description": "Blocks where all transactions respect the gas cap pass this validation gate."
        }
      ],
      "security_notes": [
        "This is the consensus-critical enforcement layer. Even if a txpool validation is bypassed (e.g., by a malicious block producer), this check ensures invalid blocks are rejected by all honest nodes.",
        "Provides block verification stability by ensuring no single transaction can dominate block processing time.",
        "Reduces worst-case block verification times, improving network synchronization and decentralization."
      ]
    },
    {
      "id": "SG-DOS-MITIGATION",
      "name": "DoS Attack Surface Reduction",
      "description": "The gas cap directly mitigates denial-of-service vectors where a single high-gas transaction could consume the entire block gas limit, causing uneven load distribution and impacting network stability.",
      "invariants": [
        {
          "id": "INV-DOS-001",
          "text": "No single transaction can consume more than 16,777,216 / block_gas_limit fraction of a block's capacity (approximately 50% of a 30M gas block, or ~40% of a 40M gas block)."
        },
        {
          "id": "INV-DOS-002",
          "text": "Every valid block must contain room for at least floor(block_gas_limit / MAX_TRANSACTION_GAS_LIMIT) - 1 additional minimum-gas transactions, ensuring no single transaction can monopolize block space."
        }
      ],
      "functions": [],
      "state_variables": [],
      "data_structures": [],
      "pre_conditions": [],
      "post_conditions": [],
      "state_transitions": [],
      "security_notes": [
        "A single transaction consuming the entire block gas limit was previously a viable DoS vector. This EIP ensures at minimum ~2 transactions per block at typical 30-40M gas limits.",
        "Reduces state bloat risk: high-gas transactions often correlate with large state changes, and capping gas limits the maximum state delta per transaction.",
        "Improves fairness of gas allocation across transactions within a block.",
        "Critical for scaling the block gas limit upward: as the gas limit increases, the cap ensures the worst-case per-transaction cost remains bounded."
      ]
    },
    {
      "id": "SG-BACKWARD-COMPATIBILITY",
      "name": "Backward Compatibility Constraints",
      "description": "Documents the backward compatibility implications of the gas cap. This is a hard fork change: transactions with gasLimit > 16,777,216 that were previously valid will be rejected after activation.",
      "invariants": [
        {
          "id": "INV-COMPAT-001",
          "text": "All transactions with gasLimit <= 16,777,216 remain fully valid and unaffected by this change."
        },
        {
          "id": "INV-COMPAT-002",
          "text": "After activation, transactions with gasLimit > 16,777,216 are universally invalid across all compliant nodes."
        }
      ],
      "functions": [],
      "state_variables": [],
      "data_structures": [],
      "pre_conditions": [],
      "post_conditions": [],
      "state_transitions": [
        {
          "id": "ST-COMPAT-001",
          "from_state": "Pre-EIP-7825 (no per-transaction gas cap)",
          "to_state": "Post-EIP-7825 (MAX_TRANSACTION_GAS_LIMIT = 2^24 enforced)",
          "trigger": "Hard fork activation at designated block/timestamp",
          "description": "After activation, the protocol transitions from no per-transaction gas cap to enforcing a 16,777,216 gas maximum per transaction. Transactions exceeding the cap that may have been valid before become invalid."
        }
      ],
      "security_notes": [
        "Empirical analysis shows minimal impact: most transactions today fall well below the 16,777,216 gas cap.",
        "Complex contract deployments and certain batch operations that exceed the cap will need to be re-architected into multiple transactions.",
        "Tooling and dApp frontends need minor updates to enforce the cap when constructing transactions."
      ]
    },
    {
      "id": "SG-CLIENT-IMPLEMENTATION",
      "name": "Client Implementation Requirements",
      "description": "Specifies the changes required in Ethereum client implementations to enforce the transaction gas limit cap at both the transaction pool and block validation layers.",
      "invariants": [
        {
          "id": "INV-CLIENT-001",
          "text": "The GAS_LIMIT parameter for transactions is capped at 16,777,216 in all compliant client implementations."
        }
      ],
      "functions": [
        {
          "id": "FN-CLIENT-001",
          "signature": "isValidTransactionGasLimit(gasLimit: uint64) -> bool",
          "description": "Utility function in client implementations to check whether a transaction's gas limit is within the protocol cap.",
          "pseudo_logic": "return gasLimit <= 16777216"
        }
      ],
      "state_variables": [
        {
          "id": "SV-CLIENT-001",
          "name": "MAX_TRANSACTION_GAS_LIMIT",
          "type": "uint64",
          "value": "16777216",
          "description": "Protocol constant to be defined in client configuration, used in both txpool validation and block validation code paths."
        }
      ],
      "data_structures": [
        {
          "id": "DS-CLIENT-001",
          "name": "TransactionValidationError",
          "description": "Error type/code returned when a transaction exceeds the gas cap.",
          "fields": [
            {
              "name": "code",
              "type": "string",
              "value": "MAX_GAS_LIMIT_EXCEEDED"
            },
            {
              "name": "message",
              "type": "string",
              "value": "Transaction gas limit exceeds maximum allowed (16,777,216)"
            }
          ]
        }
      ],
      "pre_conditions": [],
      "post_conditions": [],
      "state_transitions": [],
      "security_notes": [
        "Both txpool and block validation must independently enforce the cap for defense-in-depth.",
        "The cap check must occur before transaction execution to prevent resource exhaustion."
      ]
    }
  ],
  "metadata": {
    "timestamp": "2026-02-05T00:00:00Z",
    "eip_number": 7825,
    "authors": [
      "Giulio Rebuffo (@Giulio2002)",
      "Toni Wahrstätter (@nerolation)"
    ],
    "created": "2024-11-23",
    "discussions_url": "https://ethereum-magicians.org/t/eip-7825-transaction-gas-limit-cap/21848",
    "extraction_summary": {
      "total_subgraphs": 6,
      "total_invariants": 9,
      "total_functions": 3,
      "total_state_variables": 2,
      "total_state_transitions": 5,
      "total_pre_conditions": 2,
      "total_post_conditions": 4,
      "key_constant": "MAX_TRANSACTION_GAS_LIMIT = 16,777,216 (2^24)",
      "enforcement_layers": [
        "Transaction pool (mempool) validation",
        "Block validation (pre-execution)"
      ],
      "breaking_change": true,
      "activation_mechanism": "Hard fork"
    }
  }
}

{
  "source_url": "https://github.com/ethereum/EIPs/blob/master/EIPS/eip-7883.md",
  "title": "EIP-7883: ModExp Gas Cost Increase",
  "category": "EIP",
  "type": "Standards Track / Core",
  "status": "Final",
  "layer": "execution",
  "description": "Modifies the ModExp precompile pricing algorithm from EIP-2565: increases minimum gas from 200 to 500, triples general cost, and doubles the cost for exponents larger than 32 bytes.",
  "sub_graphs": [
    {
      "id": "SG-7883-MODEXP-GAS-COST",
      "name": "ModExp Gas Cost Calculation (Top-Level)",
      "description": "The top-level gas cost function for the ModExp precompile at address 0x0000000000000000000000000000000000000005. Computes the final gas cost as max(500, floor(multiplication_complexity * iteration_count)). This replaces the EIP-2565 formula max(200, floor(multiplication_complexity * iteration_count / 3)), raising the minimum from 200 to 500 and tripling the general cost by removing the division by 3.",
      "invariants": [
        {
          "id": "INV-7883-GAS-001",
          "text": "The gas cost MUST always be at least 500 (increased from the EIP-2565 minimum of 200)."
        },
        {
          "id": "INV-7883-GAS-002",
          "text": "The gas cost MUST equal max(500, floor(multiplication_complexity * iteration_count)) where multiplication_complexity and iteration_count are computed by their respective sub-functions."
        },
        {
          "id": "INV-7883-GAS-003",
          "text": "The gas cost MUST be a non-negative integer (result of floor applied to non-negative product, then max with 500)."
        },
        {
          "id": "INV-7883-GAS-004",
          "text": "For any given inputs, the EIP-7883 gas cost MUST be >= the EIP-2565 gas cost for the same inputs (since the minimum is higher and the divisor of 3 was removed)."
        }
      ],
      "pre_conditions": [
        {
          "id": "PRE-7883-GAS-001",
          "text": "base_length, modulus_length, and exponent_length MUST be non-negative integers derived from the input to the ModExp precompile call."
        },
        {
          "id": "PRE-7883-GAS-002",
          "text": "exponent MUST be the numeric value of the exponent input (or the first 256 bits if exponent_length > 32)."
        },
        {
          "id": "PRE-7883-GAS-003",
          "text": "This EIP MUST be active (i.e., the fork activating EIP-7883 has occurred)."
        }
      ],
      "post_conditions": [
        {
          "id": "POST-7883-GAS-001",
          "text": "The returned gas cost is an integer >= 500."
        },
        {
          "id": "POST-7883-GAS-002",
          "text": "The caller is charged exactly the returned gas amount for the ModExp precompile invocation."
        }
      ],
      "state_transitions": [],
      "functions": [
        {
          "id": "FN-7883-GAS-001",
          "name": "calculate_gas_cost",
          "signature": "def calculate_gas_cost(base_length, modulus_length, exponent_length, exponent)",
          "parameters": [
            {
              "name": "base_length",
              "type": "integer",
              "description": "The byte-length of the base input to the ModExp precompile."
            },
            {
              "name": "modulus_length",
              "type": "integer",
              "description": "The byte-length of the modulus input to the ModExp precompile."
            },
            {
              "name": "exponent_length",
              "type": "integer",
              "description": "The byte-length of the exponent input to the ModExp precompile."
            },
            {
              "name": "exponent",
              "type": "integer",
              "description": "The numeric value of the exponent (or the first 256 bits if exponent_length > 32)."
            }
          ],
          "return_type": "integer",
          "description": "Computes the gas cost for a ModExp precompile call as max(500, floor(multiplication_complexity * iteration_count)). Changed from EIP-2565 which used max(200, floor(multiplication_complexity * iteration_count / 3)).",
          "calls": [
            "calculate_multiplication_complexity",
            "calculate_iteration_count"
          ],
          "modifications": [
            "[Changed in EIP-7883] Minimum gas raised from 200 to 500",
            "[Changed in EIP-7883] Division by 3 removed, tripling the general cost"
          ]
        }
      ],
      "state_variables": [],
      "data_structures": [],
      "references": {
        "eips": [
          "EIP-2565"
        ],
        "functions_called": [
          "calculate_multiplication_complexity",
          "calculate_iteration_count"
        ]
      }
    },
    {
      "id": "SG-7883-MULT-COMPLEXITY",
      "name": "Multiplication Complexity Calculation",
      "description": "Computes the multiplication complexity factor based on the byte-lengths of the base and modulus inputs. In EIP-7883, a minimum complexity of 16 is introduced (equivalent to 4 words squared times 1, representing a 32-byte input baseline). For inputs exceeding 32 bytes, the complexity is doubled compared to EIP-2565 (2 * words^2 instead of words^2). This ensures that the ModExp precompile correctly accounts for the computational cost of large-number modular exponentiation.",
      "invariants": [
        {
          "id": "INV-7883-MULT-001",
          "text": "The multiplication_complexity MUST always be at least 16 (representing the baseline cost for inputs up to 32 bytes)."
        },
        {
          "id": "INV-7883-MULT-002",
          "text": "For max(base_length, modulus_length) <= 32, multiplication_complexity MUST equal 16."
        },
        {
          "id": "INV-7883-MULT-003",
          "text": "For max(base_length, modulus_length) > 32, multiplication_complexity MUST equal 2 * ceil(max_length / 8)^2."
        },
        {
          "id": "INV-7883-MULT-004",
          "text": "The multiplication_complexity is symmetric with respect to base_length and modulus_length (only the max of the two matters)."
        }
      ],
      "pre_conditions": [
        {
          "id": "PRE-7883-MULT-001",
          "text": "base_length and modulus_length MUST be non-negative integers."
        }
      ],
      "post_conditions": [
        {
          "id": "POST-7883-MULT-001",
          "text": "The returned multiplication_complexity is a positive integer >= 16."
        }
      ],
      "state_transitions": [],
      "functions": [
        {
          "id": "FN-7883-MULT-001",
          "name": "calculate_multiplication_complexity",
          "signature": "def calculate_multiplication_complexity(base_length, modulus_length)",
          "parameters": [
            {
              "name": "base_length",
              "type": "integer",
              "description": "The byte-length of the base input."
            },
            {
              "name": "modulus_length",
              "type": "integer",
              "description": "The byte-length of the modulus input."
            }
          ],
          "return_type": "integer",
          "description": "Computes multiplication complexity. Sets max_length = max(base_length, modulus_length), words = ceil(max_length / 8). Returns 16 if max_length <= 32, otherwise returns 2 * words^2.",
          "calls": [],
          "modifications": [
            "[Changed in EIP-7883] Baseline complexity of 16 introduced for inputs <= 32 bytes (EIP-2565 used words^2 directly, which could be as low as 1)",
            "[Changed in EIP-7883] For inputs > 32 bytes, complexity doubled from words^2 to 2 * words^2"
          ]
        }
      ],
      "state_variables": [
        {
          "id": "SV-7883-MULT-001",
          "name": "max_length",
          "type": "integer",
          "description": "The maximum of base_length and modulus_length; determines which branch of the complexity formula is used."
        },
        {
          "id": "SV-7883-MULT-002",
          "name": "words",
          "type": "integer",
          "description": "The number of 8-byte words needed to represent the larger of base or modulus: ceil(max_length / 8)."
        },
        {
          "id": "SV-7883-MULT-003",
          "name": "multiplication_complexity",
          "type": "integer",
          "description": "The computed complexity factor. Initialized to 16, then conditionally set to 2 * words^2 if max_length > 32."
        }
      ],
      "data_structures": [],
      "references": {
        "eips": [
          "EIP-2565"
        ],
        "functions_called": []
      }
    },
    {
      "id": "SG-7883-ITER-COUNT",
      "name": "Iteration Count Calculation",
      "description": "Computes the iteration count based on the exponent's byte-length and value. This represents the number of squaring/multiplication operations required. For exponents larger than 32 bytes, EIP-7883 doubles the multiplier from 8 to 16 compared to EIP-2565, making large-exponent operations more expensive. The iteration count is always at least 1.",
      "invariants": [
        {
          "id": "INV-7883-ITER-001",
          "text": "The iteration_count MUST always be at least 1."
        },
        {
          "id": "INV-7883-ITER-002",
          "text": "If exponent_length <= 32 and exponent == 0, then iteration_count MUST be 1 (clamped from 0 by the max(iteration_count, 1) floor)."
        },
        {
          "id": "INV-7883-ITER-003",
          "text": "If exponent_length <= 32 and exponent > 0, then iteration_count MUST equal exponent.bit_length() - 1 (or 1 if that value is 0, i.e. exponent == 1)."
        },
        {
          "id": "INV-7883-ITER-004",
          "text": "If exponent_length > 32, then iteration_count MUST equal (16 * (exponent_length - 32)) + ((exponent & (2^256 - 1)).bit_length() - 1), with a minimum of 1."
        }
      ],
      "pre_conditions": [
        {
          "id": "PRE-7883-ITER-001",
          "text": "exponent_length MUST be a non-negative integer."
        },
        {
          "id": "PRE-7883-ITER-002",
          "text": "exponent MUST be a non-negative integer representing the exponent value (or the first 256 bits thereof if exponent_length > 32)."
        }
      ],
      "post_conditions": [
        {
          "id": "POST-7883-ITER-001",
          "text": "The returned iteration_count is a positive integer >= 1."
        }
      ],
      "state_transitions": [],
      "functions": [
        {
          "id": "FN-7883-ITER-001",
          "name": "calculate_iteration_count",
          "signature": "def calculate_iteration_count(exponent_length, exponent)",
          "parameters": [
            {
              "name": "exponent_length",
              "type": "integer",
              "description": "The byte-length of the exponent input."
            },
            {
              "name": "exponent",
              "type": "integer",
              "description": "The numeric value of the exponent (or the first 256 bits if exponent_length > 32)."
            }
          ],
          "return_type": "integer",
          "description": "Computes the iteration count. For exponent_length <= 32: returns 0 if exponent is 0, else exponent.bit_length() - 1. For exponent_length > 32: returns (16 * (exponent_length - 32)) + ((exponent & (2^256 - 1)).bit_length() - 1). Final result is clamped to a minimum of 1.",
          "calls": [],
          "modifications": [
            "[Changed in EIP-7883] Large exponent multiplier doubled from 8 to 16 for exponent_length > 32"
          ]
        }
      ],
      "state_variables": [
        {
          "id": "SV-7883-ITER-001",
          "name": "iteration_count",
          "type": "integer",
          "description": "The computed number of iterations. Initialized to 0, then set based on exponent_length and exponent value, and finally clamped to a minimum of 1."
        }
      ],
      "data_structures": [],
      "references": {
        "eips": [
          "EIP-2565"
        ],
        "functions_called": []
      }
    },
    {
      "id": "SG-7883-PRICE-CHANGE-1",
      "name": "Pricing Change: Minimum and General Cost Increase",
      "description": "Describes the first pricing change in EIP-7883: the minimum gas cost is raised from 200 to 500, and the general cost is tripled by removing the division by 3 in the final gas cost formula. This addresses scenarios where the ModExp precompile was underpriced relative to its computational cost, particularly for small inputs that would hit the minimum gas floor.",
      "invariants": [
        {
          "id": "INV-7883-PC1-001",
          "text": "The minimum gas cost for any ModExp call MUST be 500 (previously 200 under EIP-2565)."
        },
        {
          "id": "INV-7883-PC1-002",
          "text": "The general cost formula MUST NOT include a division by 3 (previously: floor(complexity * iterations / 3); now: floor(complexity * iterations))."
        },
        {
          "id": "INV-7883-PC1-003",
          "text": "For the most common historical ModExp usage patterns (~99.69% of calls), the gas cost increase MUST be between 150% (200 -> 500 minimum) and 200% (tripling of base cost)."
        }
      ],
      "pre_conditions": [],
      "post_conditions": [],
      "state_transitions": [
        {
          "id": "ST-7883-PC1-001",
          "text": "Gas cost formula transitions from max(200, floor(multiplication_complexity * iteration_count / 3)) to max(500, floor(multiplication_complexity * iteration_count)).",
